INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(6950, 'vital signs', '/ˈvaɪtəl saɪnz/', 'noun', '{"zh-TW":["生命體徵"],"en":["measurements of the basic body functions"]}', NULL, 'check vital signs / monitor vital signs', '[{"en":"The nurse checked the patient''s vital signs every hour.","zh-TW":"護士每小時檢查病患的生命體徵。"},{"en":"Vital signs include temperature, pulse, and blood pressure.","zh-TW":"生命體徵包括體溫、脈搏和血壓。"}]', NULL, NULL, 4, 6950, NULL),
(6951, 'vocational', '/''vəʊˈkeɪʃənəl/', 'adjective', '{"zh-TW":["職業的；技術的"],"en":["relating to the skills or training needed for a particular job or profession"]}', NULL, 'vocational school / vocational training / vocational course', '[{"en":"Vocational courses prepare students directly for careers in skilled trades.","zh-TW":"職業課程使學生直接為技術行業的職業做好準備。"},{"en":"The government invested in vocational education to address the skills shortage.","zh-TW":"政府投資職業教育以解決技術短缺問題。"}]', '{"noun":"vocation"}', NULL, 4, 6951, NULL),
(6952, 'vocational training', '/vəʊˈkeɪʃənəl ˈtreɪnɪŋ/', 'noun', '{"zh-TW":["職業培訓；技職教育"],"en":["education focused on practical job skills"]}', NULL, 'enroll in vocational training / vocational training program', '[{"en":"Vocational training programs prepare students for specific careers.","zh-TW":"職業培訓計劃為學生準備特定職業。"},{"en":"The government funds vocational training to reduce unemployment.","zh-TW":"政府資助職業培訓以降低失業率。"}]', '{"adjective":"vocational"}', NULL, 5, 6952, NULL),
(6953, 'voice acting', '/vɔɪs ˈæktɪŋ/', 'noun', '{"zh-TW":["配音表演；聲音演繹"],"en":["the performance of voice-over work for animated or dubbed content"]}', NULL, 'professional voice acting / voice acting career / voice acting industry', '[{"en":"Voice acting for animated films requires a unique set of expressive skills.","zh-TW":"動畫電影的配音表演需要一套獨特的表達技能。"},{"en":"The voice acting cast brought the animated characters to vivid life.","zh-TW":"配音演員讓動畫角色栩栩如生地活了起來。"}]', '{"noun":"voice actor"}', NULL, 4, 6953, NULL),
(6954, 'void', '/vɔɪd/', 'adjective', '{"zh-TW":["無效的；無法律效力的"],"en":["having no legal force or effect"]}', NULL, 'render void / null and void / void contract', '[{"en":"A contract signed under duress may be rendered void.","zh-TW":"在脅迫下簽署的合約可能被視為無效。"},{"en":"The court declared the agreement null and void.","zh-TW":"法院宣佈協議無效。"}]', '{"verb":"void","noun":"voidance"}', NULL, 1, 6954, NULL),
(6955, 'void ab initio', '/vɔɪd æb ɪˈnɪʃiəʊ/', 'phrase', '{"zh-TW":["自始無效的"],"en":["null and void from the beginning"]}', NULL, 'declare void ab initio / void ab initio contract / treated as void ab initio', '[{"en":"A contract signed under duress may be declared void ab initio.","zh-TW":"在脅迫下簽署的合約可能被宣告自始無效。"},{"en":"Fraud renders a contract void ab initio in most jurisdictions.","zh-TW":"在大多數司法管轄區，欺詐使合約自始無效。"}]', NULL, NULL, 5, 6955, NULL),
(6956, 'void contract', '/vɔɪd ˈkɒntrækt/', 'noun', '{"zh-TW":["無效合約"],"en":["an agreement that is unenforceable under law from the moment it was created"]}', NULL, 'declare a void contract / void contract clause', '[{"en":"A contract signed under duress may be declared a void contract.","zh-TW":"在脅迫下簽署的合約可能被宣布為無效合約。"},{"en":"Fraud in the formation of an agreement renders it a void contract.","zh-TW":"協議簽訂過程中的欺詐行為使其成為無效合約。"}]', '{"opposite":"valid contract","synonym2":"null and void contract"}', NULL, 5, 6956, NULL),
(6957, 'voidable contract', '/ˈvɔɪdəbəl ˈkɒntrækt/', 'noun', '{"zh-TW":["可撤銷合約"],"en":["a contract that is valid until one party chooses to cancel it due to a legal defect"]}', NULL, 'enter into a voidable contract / rescind a voidable contract / make a contract voidable', '[{"en":"A contract signed under duress is voidable at the option of the party under pressure.","zh-TW":"在脅迫下簽訂的合約可由受壓方選擇撤銷。"},{"en":"Misrepresentation by either party can render a contract voidable.","zh-TW":"任何一方的虛假陳述都可能使合約成為可撤銷的合約。"}]', NULL, NULL, 5, 6957, NULL),
(6958, 'volatile', '/ˈvɑːlətl/', 'adjective', '{"zh-TW":["波動的；不穩定的"],"en":["liable to change rapidly and unpredictably"]}', NULL, 'volatile market / volatile prices / highly volatile', '[{"en":"The stock market has been highly volatile this year.","zh-TW":"今年股市波動劇烈。"},{"en":"Oil prices remain volatile due to geopolitical tensions.","zh-TW":"由於地緣政治緊張，油價持續波動。"}]', '{"noun":"volatility","adjective":"volatile"}', NULL, 3, 6958, NULL),
(6959, 'volatility', '/ˌvɒləˈtɪlɪti/', 'noun', '{"zh-TW":["波動性；波動率"],"en":["the degree of variation in a financial instrument''s price over time"]}', NULL, 'market volatility / high volatility / volatility index / manage volatility', '[{"en":"Market volatility increased sharply during the crisis.","zh-TW":"危機期間市場波動性急劇增加。"},{"en":"Investors avoid high-volatility stocks during uncertain times.","zh-TW":"投資者在不確定時期避開高波動性股票。"}]', '{"adjective":"volatile"}', NULL, 4, 6959, NULL),
(6960, 'volatility clustering', '/ˌvɒlɪˈtɪlɪti ˈklʌstərɪŋ/', 'noun', '{"zh-TW":["波動率聚集"],"en":["the tendency for large market moves to be followed by more large moves"]}', NULL, 'observe volatility clustering / model volatility clustering / volatility clustering effect', '[{"en":"Volatility clustering means financial risk is not evenly distributed over time.","zh-TW":"波動率聚集意味著金融風險不是隨時間均勻分布的。"},{"en":"GARCH models are designed to capture volatility clustering in financial returns.","zh-TW":"GARCH模型旨在捕捉金融收益中的波動率聚集。"}]', NULL, NULL, 5, 6960, NULL),
(6961, 'volcano', '/vɒlˈkeɪnoʊ/', 'noun', '{"zh-TW":["火山"],"en":["a mountain that can erupt with lava and ash"]}', '{"root":{"text":"Vulcan","meaning":"Roman god of fire (火神)"},"logic":"以羅馬火神 Vulcan 命名。"}', 'active volcano / volcanic eruption', '[{"en":"The volcano erupted without warning.","zh-TW":"火山毫無預警地噴發。"},{"en":"Hawaii has several active volcanoes.","zh-TW":"夏威夷有幾座活火山。"}]', '{"adjective":"volcanic","noun":"volcanism"}', NULL, 3, 6961, NULL),
(6962, 'volume', '/ˈvɑːljuːm/', 'noun', '{"zh-TW":["量；體積","音量；冊"],"en":["the amount or quantity","the degree of loudness"]}', NULL, 'sales volume / high volume / trading volume', '[{"en":"Sales volume increased by 25% this year.","zh-TW":"今年銷售量增加了25%。"},{"en":"High-volume production reduces unit costs.","zh-TW":"大量生產降低了單位成本。"}]', '{"noun":"volume","adjective":"voluminous"}', NULL, 2, 6962, 241),
(6963, 'volume discount', '/ˈvɒljuːm ˈdɪskaʊnt/', 'noun', '{"zh-TW":["數量折扣；批量折扣"],"en":["a price reduction given for purchasing large quantities"]}', NULL, 'offer a volume discount / qualify for a volume discount', '[{"en":"Customers ordering over 1000 units receive a 10% volume discount.","zh-TW":"訂購超過1000件的客戶可獲得10%的數量折扣。"},{"en":"The volume discount made the bulk order more cost-effective.","zh-TW":"數量折扣使大量訂購更具成本效益。"}]', NULL, NULL, 5, 6963, NULL),
(6964, 'voluntary', '/ˈvɑːlənteri/', 'adjective', '{"zh-TW":["自願的；志願的"],"en":["done by choice; not compulsory"]}', NULL, 'voluntary participation / voluntary redundancy / voluntary work', '[{"en":"Participation in the survey is voluntary.","zh-TW":"參與調查是自願的。"},{"en":"The company offered voluntary redundancy packages.","zh-TW":"公司提供了自願離職方案。"}]', '{"adjective":"voluntary","adverb":"voluntarily","noun":"volunteer"}', NULL, 3, 6964, 482),
(6965, 'volunteer', '/ˌvɑːlənˈtɪr/', 'noun, verb', '{"zh-TW":["志工；志願者","自願做"],"en":["a person who works without pay","to offer to do something willingly"]}', NULL, 'volunteer work / volunteer for / community volunteer', '[{"en":"Many employees volunteer for community projects.","zh-TW":"許多員工自願參加社區專案。"},{"en":"She volunteered to lead the new initiative.","zh-TW":"她自願領導新的倡議。"}]', '{"noun":"volunteer","verb":"volunteer","adjective":"voluntary"}', NULL, 3, 6965, NULL),
(6966, 'voting rights', '/ˈvoʊtɪŋ raɪts/', 'noun', '{"zh-TW":["投票權；表決權"],"en":["the rights of shareholders to vote on corporate decisions at a general meeting"]}', NULL, 'grant voting rights / voting rights per share', '[{"en":"Common shareholders have voting rights while preferred shareholders often do not.","zh-TW":"普通股股東擁有投票權，而優先股股東通常沒有。"},{"en":"The merger required approval from shareholders with majority voting rights.","zh-TW":"合併需要獲得持有多數投票權的股東批准。"}]', NULL, NULL, 5, 6966, NULL),
(6967, 'voucher', '/ˈvaʊtʃər/', 'noun', '{"zh-TW":["憑證；代金券"],"en":["a document that entitles the holder to a discount or service"]}', NULL, 'gift voucher / discount voucher / redeem a voucher', '[{"en":"Customers received a $10 gift voucher.","zh-TW":"顧客獲得了一張10美元的禮品券。"},{"en":"The voucher is valid for 30 days.","zh-TW":"該優惠券有效期為30天。"}]', '{"noun":"voucher"}', NULL, 3, 6967, NULL),
(6968, 'VPN', '/viː piː ɛn/', 'noun', '{"zh-TW":["虛擬私人網路"],"en":["a secure network connection that encrypts internet traffic"]}', NULL, 'use a VPN / VPN access', '[{"en":"Employees must use a VPN when working remotely.","zh-TW":"員工遠端工作時必須使用VPN。"},{"en":"The VPN protects company data on public Wi-Fi networks.","zh-TW":"VPN在公共無線網路上保護公司數據。"}]', NULL, NULL, 1, 6968, NULL),
(6969, 'vulnerable', '/ˈvʌlnərəbl/', 'adjective', '{"zh-TW":["脆弱的；易受攻擊的"],"en":["susceptible to harm or attack"]}', NULL, 'vulnerable to / vulnerable position / economically vulnerable', '[{"en":"Small businesses are vulnerable to economic downturns.","zh-TW":"小型企業容易受經濟衰退的影響。"},{"en":"The system is vulnerable to cyber attacks.","zh-TW":"該系統容易受到網路攻擊。"}]', '{"noun":"vulnerability","adjective":"vulnerable"}', NULL, 4, 6969, NULL),
(6970, 'wage', '/weɪdʒ/', 'noun', '{"zh-TW":["工資；薪水"],"en":["a fixed regular payment for work, usually hourly"]}', NULL, 'minimum wage / wage increase / hourly wage', '[{"en":"The minimum wage was raised to $15 per hour.","zh-TW":"最低工資提高到每小時15美元。"},{"en":"Workers demanded a wage increase.","zh-TW":"工人要求加薪。"}]', '{"noun":"wage, wages"}', NULL, 1, 6970, NULL),
(6971, 'wage freeze', '/weɪdʒ friːz/', 'noun', '{"zh-TW":["工資凍結"],"en":["a policy of not increasing wages for a defined period"]}', NULL, 'implement a wage freeze / end the wage freeze', '[{"en":"A wage freeze was imposed across the organization to reduce costs.","zh-TW":"為降低成本在全組織範圍內實施了工資凍結。"},{"en":"After the wage freeze, staff received a 5% catch-up increase.","zh-TW":"工資凍結結束後，員工獲得了5%的補償性加薪。"}]', NULL, NULL, 4, 6971, NULL),
(6972, 'wage gap', '/weɪdʒ ɡæp/', 'noun', '{"zh-TW":["薪資差距"],"en":["the difference in earnings between different groups of workers"]}', NULL, 'address the wage gap / gender wage gap', '[{"en":"The company conducted a study to assess the gender wage gap.","zh-TW":"公司進行了一項研究以評估性別薪資差距。"},{"en":"Closing the wage gap requires transparent pay policies.","zh-TW":"縮小薪資差距需要透明的薪酬政策。"}]', NULL, NULL, 3, 6972, NULL),
(6973, 'wage growth', '/weɪdʒ ɡroʊθ/', 'noun', '{"zh-TW":["薪資增長"],"en":["the increase in wages over a given period"]}', NULL, 'accelerate wage growth / above-average wage growth', '[{"en":"Strong wage growth boosted consumer spending.","zh-TW":"強勁的薪資增長提升了消費者支出。"},{"en":"Wage growth lagged behind inflation, reducing real purchasing power.","zh-TW":"薪資增長落後於通脹，降低了實際購買力。"}]', NULL, NULL, 4, 6973, NULL),
(6974, 'wait', 'weɪt', 'verb', '{"zh-TW":["等待；等候","服務"],"en":["to stay until something happens","to serve at table"]}', NULL, 'wait for approval/a response', '[{"en":"Please wait for confirmation.","zh-TW":"請等待確認。"}]', '{"noun":"wait, waiter","adjective":"waiting"}', NULL, 1, 6974, NULL),
(6975, 'waiter', '/ˈweɪtər/', 'noun', '{"zh-TW":["服務生；侍者"],"en":["a person who serves food in a restaurant"]}', NULL, 'ask the waiter / experienced waiter', '[{"en":"The waiter was attentive and friendly throughout the meal.","zh-TW":"服務生在整個用餐過程中都很周到友善。"},{"en":"Please ask the waiter for today''s soup of the day.","zh-TW":"請詢問服務生今日例湯。"}]', '{"noun":"waitress","verb":"wait"}', NULL, 2, 6975, NULL),
(6976, 'waiting period', '/ˈweɪtɪŋ ˈpɪəriəd/', 'noun', '{"zh-TW":["等待期間"],"en":["a period before insurance benefits become effective"]}', NULL, 'waiting period requirement / six-month waiting period', '[{"en":"There is a six-month waiting period for maternity benefits.","zh-TW":"生育福利有六個月的等待期間。"},{"en":"The waiting period begins from the date of enrollment.","zh-TW":"等待期間從入保日期開始計算。"}]', NULL, NULL, 5, 6976, NULL),
(6977, 'waiting room', '/ˈweɪtɪŋ ruːm/', 'noun', '{"zh-TW":["候診室；等候室"],"en":["a room where patients wait before being seen"]}', NULL, 'sit in the waiting room / waiting room etiquette', '[{"en":"The waiting room was full of patients.","zh-TW":"候診室裡坐滿了患者。"},{"en":"Please wait in the waiting room until your name is called.","zh-TW":"請在候診室等候，直到叫到您的名字。"}]', NULL, NULL, 4, 6977, NULL),
(6978, 'waitlist', '/''weɪtlɪst/', 'noun', '{"zh-TW":["候補名單；等待名單"],"en":["a list of people waiting for something that is currently unavailable"]}', NULL, 'on the waitlist / join the waitlist / waitlist notification', '[{"en":"She was on the waitlist for the sold-out flight and got a seat at the last minute.","zh-TW":"她在售罄航班的候補名單上，並在最後一刻得到了一個座位。"},{"en":"The popular restaurant had a waitlist of over two hours on weekends.","zh-TW":"這家受歡迎的餐廳週末等待名單超過兩小時。"}]', NULL, NULL, 3, 6978, NULL),
(6979, 'waive', '/weɪv/', 'verb', '{"zh-TW":["放棄（權利）；免除"],"en":["to refrain from insisting on a right or claim"]}', NULL, 'waive a fee / waive the right / waive requirements', '[{"en":"The bank waived the processing fee.","zh-TW":"銀行免除了手續費。"},{"en":"She waived her right to appeal.","zh-TW":"她放棄了上訴權。"}]', '{"noun":"waiver","verb":"waive"}', NULL, 2, 6979, NULL),
(6980, 'waiver', '/ˈweɪvər/', 'noun', '{"zh-TW":["棄權；豁免聲明"],"en":["a voluntary relinquishment of a right or claim"]}', NULL, 'sign a waiver / liability waiver', '[{"en":"Participants must sign a liability waiver before joining.","zh-TW":"參與者在加入前必須簽署責任豁免聲明。"},{"en":"The company issued a waiver for the late payment.","zh-TW":"公司對逾期付款發出了豁免聲明。"}]', '{"verb":"waive"}', NULL, 2, 6980, NULL),
(6981, 'wake-up call', '/ˈweɪk ʌp kɔːl/', 'noun', '{"zh-TW":["叫醒服務"],"en":["a phone call to wake a guest at a requested time"]}', NULL, 'request a wake-up call / early wake-up call', '[{"en":"Please request a wake-up call for 6 am.","zh-TW":"請要求早上6點的叫醒服務。"},{"en":"The front desk will arrange a wake-up call for you.","zh-TW":"前台將為您安排叫醒服務。"}]', NULL, NULL, 4, 6981, NULL),
(6982, 'walk', 'wɔːk', 'verb', '{"zh-TW":["步行；走","帶領"],"en":["to move on foot","to guide through something"]}', NULL, 'walk through a process', '[{"en":"Let me walk you through the steps.","zh-TW":"讓我帶您了解這些步驟。"}]', '{"noun":"walk, walker","adjective":"walking"}', NULL, 1, 6982, NULL),
(6983, 'wander', '/''wɒndər/', 'verb', '{"zh-TW":["漫步；閒逛"],"en":["to walk or move in a leisurely, casual, or aimless way"]}', NULL, 'wander around / wander through / wander aimlessly', '[{"en":"They wandered through the cobblestone streets without any particular plan.","zh-TW":"他們漫步在鵝卵石街道上，沒有任何特定計劃。"},{"en":"I love to wander through the local market on Saturday mornings.","zh-TW":"我喜歡在星期六早上漫步在當地市場。"}]', '{"noun":"wanderer"}', NULL, 2, 6983, NULL),
(6984, 'wanderlust', '/''wɒndərlʌst/', 'noun', '{"zh-TW":["對旅行的渴望；流浪癖"],"en":["a strong desire to travel and explore the world"]}', NULL, 'feel wanderlust / satisfy wanderlust / overcome wanderlust', '[{"en":"Her wanderlust led her to visit over fifty countries before the age of thirty.","zh-TW":"她對旅行的渴望讓她在三十歲之前走訪了超過五十個國家。"},{"en":"His wanderlust was so strong that he quit his job to travel the world.","zh-TW":"他對旅行的渴望如此強烈，以至於他辭掉工作去環遊世界。"}]', NULL, NULL, 4, 6984, NULL),
(6985, 'want', 'wɒnt', 'verb', '{"zh-TW":["【主要意義-動詞】想要；希望","【次要意義-名詞】缺乏；匱乏；貧困"],"en":["[primary - verb] to desire or wish for something","[secondary - noun] a lack or shortage; poverty"]}', NULL, 'for want of / in want / want for nothing', '[{"en":"The project failed for want of adequate funding.","zh-TW":"由於缺乏足夠的資金，這個專案失敗了。"},{"en":"Many families in the region live in want.","zh-TW":"該地區許多家庭生活在貧困中。"},{"en":"The plan was abandoned for want of support from upper management.","zh-TW":"由於缺乏高層管理的支持，該計劃被放棄了。"}]', '{"adjective":"wanting"}', '名詞 want 意為「缺乏/匱乏」，片語 for want of = 由於缺乏……，常見於 TOEIC 閱讀正式書面語境，容易與動詞用法混淆。', 1, 6985, NULL),
(6986, 'ward round', '/wɔːrd raʊnd/', 'noun', '{"zh-TW":["巡房；病房巡診"],"en":["a visit by a doctor to all patients in a ward"]}', NULL, 'conduct a ward round / morning ward round / ward round assessment', '[{"en":"The consultant performs a ward round every morning to review patients.","zh-TW":"顧問醫師每天早上進行巡房審查患者情況。"},{"en":"Ward rounds ensure patients receive timely updates on their treatment.","zh-TW":"巡房確保患者及時獲得治療進展的更新。"}]', NULL, NULL, 4, 6986, NULL),
(6987, 'warehouse', '/ˈwerhɑʊs/', 'noun', '{"zh-TW":["倉庫；貨倉"],"en":["a large building for storing goods"]}', NULL, 'warehouse management / distribution warehouse / warehouse space', '[{"en":"The new warehouse doubles our storage capacity.","zh-TW":"新倉庫使我們的儲存容量翻倍。"},{"en":"Goods are shipped directly from the warehouse.","zh-TW":"貨物直接從倉庫出貨。"}]', '{"noun":"warehouse, warehousing"}', NULL, 3, 6987, 242),
(6988, 'warehousing', '/''weərˌhaʊzɪŋ/', 'noun', '{"zh-TW":["倉儲；倉庫業務"],"en":["the activity or business of storing goods in a warehouse"]}', NULL, 'cost of warehousing / efficient warehousing / outsource warehousing', '[{"en":"Outsourcing warehousing can reduce costs for small businesses.","zh-TW":"外包倉儲可以為小型企業降低成本。"},{"en":"Automated warehousing systems improve speed and accuracy in order fulfillment.","zh-TW":"自動化倉儲系統提高了訂單履行的速度和準確性。"}]', '{"noun":"warehouse"}', NULL, 4, 6988, NULL),
(6989, 'warm lead', '/wɔːrm liːd/', 'noun', '{"zh-TW":["暖潛在客戶；有意向客戶"],"en":["a potential customer who has already shown interest in a product"]}', NULL, 'follow up on warm leads / convert warm leads / qualify warm leads', '[{"en":"Warm leads are far more likely to convert than cold ones.","zh-TW":"暖潛在客戶比冷潛在客戶更有可能轉換。"},{"en":"She focused on warm leads to shorten the sales cycle.","zh-TW":"她專注於暖潛在客戶以縮短銷售週期。"}]', NULL, NULL, 3, 6989, NULL),
(6990, 'warm up', '/''wɔːrm ʌp/', 'verb', '{"zh-TW":["熱身；做準備運動"],"en":["to prepare the body for exercise by performing light activities"]}', NULL, 'warm up before exercise / warm up properly / spend time warming up', '[{"en":"It is important to warm up before any strenuous physical activity.","zh-TW":"在任何劇烈體育活動之前熱身是很重要的。"},{"en":"The athletes spent twenty minutes warming up before the championship game.","zh-TW":"運動員在錦標賽比賽前花了二十分鐘熱身。"}]', NULL, NULL, 3, 6990, NULL),
(6991, 'warm-up', '/''wɔːrm ʌp/', 'noun', '{"zh-TW":["暖身；熱身活動"],"en":["a period of gentle exercise done before more intense physical activity"]}', NULL, 'do a warm-up / proper warm-up / dynamic warm-up', '[{"en":"A proper warm-up reduces the risk of injury during exercise.","zh-TW":"適當的暖身可以降低運動時受傷的風險。"},{"en":"The team spent fifteen minutes on a warm-up before the match began.","zh-TW":"球隊在比賽開始前花了十五分鐘進行暖身。"}]', '{"verb":"warm up"}', NULL, 3, 6991, NULL),
(6992, 'warm-up exercise', '/''wɔːrm ʌp ˌeksəsaɪz/', 'noun', '{"zh-TW":["熱身運動；準備活動"],"en":["light physical activity done before more intense exercise to prepare the body"]}', NULL, 'do warm-up exercises / complete warm-up exercises / skip warm-up exercises', '[{"en":"The trainer guided the group through five minutes of warm-up exercises.","zh-TW":"教練帶領大家完成了五分鐘的熱身運動。"},{"en":"Never skip warm-up exercises before a strenuous workout to prevent injuries.","zh-TW":"劇烈運動前千萬不要跳過熱身運動，以防止受傷。"}]', NULL, NULL, 5, 6992, NULL),
(6993, 'warrant', '/ˈwɒrənt/', 'noun', '{"zh-TW":["搜索令；逮捕令","授權令；正當理由","保證；使有正當理由"],"en":["an official document allowing police action","a document authorizing action; justification","to justify; to guarantee"]}', NULL, 'search warrant / arrest warrant; warrant attention / arrest warrant / warrant further investigation', '[{"en":"Police obtained a search warrant.","zh-TW":"警方取得了搜索令。"},{"en":"There''s a warrant for his arrest.","zh-TW":"有一張對他的逮捕令。"},{"en":"The situation warrants immediate action.","zh-TW":"情況需要立即採取行動。"},{"en":"The findings warrant further investigation.","zh-TW":"這些發現值得進一步調查。"}]', '{"verb":"warrant","noun":"warrant, warranty"}', NULL, 3, 6993, NULL),
(6994, 'warranty', '/ˈwɒrənti/', 'noun', '{"zh-TW":["保固；保證書"],"en":["a written guarantee of product repair or replacement","a guarantee about the condition of a product"]}', '{"root":{"text":"warrant","meaning":"guarantee (保證)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"保證的狀態，即「保固」。"}', 'under warranty / warranty period / extended warranty', '[{"en":"The laptop is still under warranty.","zh-TW":"這台筆電還在保固期內。"},{"en":"Would you like to purchase an extended warranty?","zh-TW":"你要購買延長保固嗎？"},{"en":"The product comes with a two-year warranty.","zh-TW":"該產品附有兩年保固。"},{"en":"Repairs are free if the item is still under warranty.","zh-TW":"如果商品仍在保固期內，維修免費。"}]', '{"noun":"warranty, warrant"}', NULL, 3, 6994, NULL),
(6995, 'warranty claim', '/ˈwɒrənti kleɪm/', 'noun', '{"zh-TW":["保固索賠"],"en":["a request to repair or replace a product under warranty"]}', NULL, 'file a warranty claim / valid warranty claim', '[{"en":"She filed a warranty claim for the defective laptop.","zh-TW":"她就有問題的筆記型電腦提出了保固索賠。"},{"en":"Warranty claims must be submitted within the warranty period.","zh-TW":"保固索賠必須在保固期內提交。"}]', NULL, NULL, 5, 6995, NULL),
(6996, 'waste', '/weɪst/', 'noun, verb', '{"zh-TW":["浪費；廢物","浪費"],"en":["unwanted material; extravagant use","to use carelessly"]}', NULL, 'waste of time / reduce waste / waste disposal', '[{"en":"The company reduced waste by 30% through recycling.","zh-TW":"公司透過回收減少了30%的廢物。"},{"en":"Don''t waste time on unnecessary meetings.","zh-TW":"不要把時間浪費在不必要的會議上。"}]', '{"noun":"waste, wastage","verb":"waste","adjective":"wasteful"}', NULL, 2, 6996, 483),
(6997, 'wastewater treatment', '/ˈweɪstwɔːtər ˈtriːtmənt/', 'noun', '{"zh-TW":["污水處理；廢水處理"],"en":["the process of removing contaminants from water before discharge"]}', NULL, 'wastewater treatment plant / advanced wastewater treatment / wastewater treatment process', '[{"en":"Effective wastewater treatment prevents river and ocean pollution.","zh-TW":"有效的污水處理防止河流和海洋污染。"},{"en":"Investment in wastewater treatment infrastructure is a public health priority.","zh-TW":"投資污水處理基礎設施是公共衛生優先事項。"}]', NULL, NULL, 5, 6997, NULL),
(6998, 'watch', 'wɒtʃ', 'verb', '{"zh-TW":["觀看；注意","監視"],"en":["to look at something carefully","to monitor"]}', NULL, 'watch a trend/presentation', '[{"en":"Watch for any unusual expenses.","zh-TW":"注意任何不尋常的費用。"}]', '{"noun":"watch, watcher","adjective":"watchful","adverb":"watchfully"}', NULL, 2, 6998, NULL),
(6999, 'water conservation', '/ˈwɔːtər ˌkɒnsəˈveɪʃən/', 'noun', '{"zh-TW":["水資源保育；節水"],"en":["the careful use and protection of water resources"]}', NULL, 'promote water conservation / water conservation measure', '[{"en":"Water conservation is critical in drought-prone regions.","zh-TW":"水資源保育在乾旱易發地區至關重要。"},{"en":"Simple steps like fixing leaks support water conservation.","zh-TW":"修復漏水等簡單措施有助於節水。"}]', NULL, NULL, 5, 6999, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(7000, 'water scarcity', '/ˈwɔːtər ˈskeərsɪti/', 'noun', '{"zh-TW":["水資源匱乏；水荒"],"en":["a shortage of fresh water affecting communities and ecosystems"]}', NULL, 'address water scarcity / water scarcity crisis / water scarcity solutions', '[{"en":"Climate change is expected to worsen water scarcity in many regions.","zh-TW":"氣候變化預計將惡化許多地區的水資源匱乏狀況。"},{"en":"Water scarcity forces communities to choose between agriculture and drinking water.","zh-TW":"水資源匱乏迫使社區在農業和飲用水之間做出選擇。"}]', NULL, NULL, 5, 7000, NULL),
(7001, 'waterfall', '/''wɔːtəfɔːl/', 'noun', '{"zh-TW":["瀑布"],"en":["a cascade of water falling from a height, formed when a river flows over a precipice"]}', NULL, 'magnificent waterfall / visit a waterfall / waterfall hike', '[{"en":"The waterfall at the end of the trail was worth the three-hour hike.","zh-TW":"小徑盡頭的瀑布值得三小時的徒步旅行。"},{"en":"Visitors can swim in the pool at the base of the waterfall.","zh-TW":"遊客可以在瀑布底部的水潭游泳。"}]', NULL, NULL, 3, 7001, NULL),
(7002, 'waterfall methodology', '/ˈwɔːtərfɔːl meθəˈdɒlədʒi/', 'noun', '{"zh-TW":["瀑布式開發方法論"],"en":["a sequential project management approach where phases follow one after another"]}', NULL, 'waterfall methodology phases / use waterfall methodology', '[{"en":"The waterfall methodology requires completing each phase before moving to the next.","zh-TW":"瀑布式開發方法論要求在進入下一階段前完成每個階段。"},{"en":"Waterfall is suitable for projects with clearly defined requirements.","zh-TW":"瀑布式開發適用於需求明確的項目。"}]', NULL, NULL, 5, 7002, NULL),
(7003, 'way', 'weɪ', 'noun', '{"zh-TW":["方式；方法","路途"],"en":["a method or manner","a route or path"]}', NULL, 'find a way/on the way', '[{"en":"Is there a better way to handle this?","zh-TW":"有更好的方法來處理這個問題嗎？"}]', '{"adjective":"wayward","adverb":"anyway"}', NULL, 1, 7003, NULL),
(7004, 'wealth', '/welθ/', 'noun', '{"zh-TW":["財富；豐富"],"en":["an abundance of possessions or resources"]}', NULL, 'wealth management / wealth of experience / accumulate wealth', '[{"en":"Wealth management services cater to high-net-worth individuals.","zh-TW":"財富管理服務面向高淨值人士。"},{"en":"She brings a wealth of experience to the role.","zh-TW":"她為這個職位帶來了豐富的經驗。"}]', '{"noun":"wealth","adjective":"wealthy"}', NULL, 2, 7004, 484),
(7005, 'wealth accumulation', '/welθ ˌækjʊmjʊˈleɪʃən/', 'noun', '{"zh-TW":["財富積累"],"en":["the process of gradually building financial assets over time"]}', NULL, 'focus on wealth accumulation / wealth accumulation strategy', '[{"en":"Long-term investment is the most reliable path to wealth accumulation.","zh-TW":"長期投資是財富積累最可靠的途徑。"},{"en":"Compound interest is a powerful tool for wealth accumulation.","zh-TW":"複利是財富積累的強大工具。"}]', NULL, NULL, 5, 7005, NULL),
(7006, 'wealth management', '/welθ ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["財富管理"],"en":["financial services providing investment advice and management to high-net-worth clients"]}', NULL, 'use a wealth management firm / wealth management services', '[{"en":"She engaged a wealth management firm to manage her investment portfolio.","zh-TW":"她聘請了一家財富管理公司管理她的投資組合。"},{"en":"Wealth management services include tax planning and estate management.","zh-TW":"財富管理服務包括稅務規劃和遺產管理。"}]', NULL, NULL, 5, 7006, NULL),
(7007, 'weather', '/ˈweðər/', 'noun', '{"zh-TW":["天氣"],"en":["the state of the atmosphere at a particular time"]}', '{"root":{"text":"weather","meaning":"wind/air (風/空氣)"},"logic":"源自古英語 weder（大氣狀態）。"}', 'weather forecast / bad weather / weather conditions', '[{"en":"What''s the weather like today?","zh-TW":"今天天氣如何？"},{"en":"Bad weather delayed our flight.","zh-TW":"惡劣天氣延誤了我們的航班。"}]', '{"verb":"weather"}', NULL, 3, 7007, NULL),
(7008, 'web browser', '/wɛb ˈbraʊzər/', 'noun', '{"zh-TW":["網頁瀏覽器"],"en":["software used to access and navigate the internet"]}', NULL, 'open a web browser / web browser compatibility', '[{"en":"Clear your web browser''s cache to improve performance.","zh-TW":"清除您的網頁瀏覽器快取以提升效能。"},{"en":"The website is compatible with all major web browsers.","zh-TW":"該網站與所有主要網頁瀏覽器相容。"}]', NULL, NULL, 4, 7008, NULL),
(7009, 'webhook', '/ˈwebhʊk/', 'noun', '{"zh-TW":["網路回調；Webhook"],"en":["a way for apps to receive automated notifications when events occur"]}', NULL, 'configure a webhook / webhook endpoint / trigger a webhook', '[{"en":"The payment system uses a webhook to notify the server of successful transactions.","zh-TW":"支付系統使用Webhook通知伺服器成功交易。"},{"en":"Webhooks eliminate the need to poll an API for status updates.","zh-TW":"Webhook消除了輪詢API進行狀態更新的需要。"}]', NULL, NULL, 3, 7009, NULL),
(7010, 'website', '/ˈwɛbsaɪt/', 'noun', '{"zh-TW":["網站"],"en":["a set of pages on the internet"]}', NULL, 'visit a website / website design', '[{"en":"Visit our website for more info.","zh-TW":"請訪問我們的網站了解更多資訊。"},{"en":"The website was redesigned last month.","zh-TW":"網站上個月重新設計了。"}]', NULL, NULL, 3, 7010, NULL),
(7011, 'weight class', '/''weɪt klɑːs/', 'noun', '{"zh-TW":["量級；體重級別"],"en":["a category based on body weight within which competitors are matched in combat sports"]}', NULL, 'fight in the same weight class / move up a weight class / weight class limit', '[{"en":"The boxer moved up to the next weight class to face new competition.","zh-TW":"這位拳擊手晉升到更高的量級以面對新的競爭。"},{"en":"Wrestlers must stay within their weight class during competition.","zh-TW":"摔跤手在比賽期間必須保持在他們的量級範圍內。"}]', NULL, NULL, 4, 7011, NULL),
(7012, 'weight room', '/''weɪt ruːm/', 'noun', '{"zh-TW":["重量訓練室；舉重室"],"en":["a room in a gym or sports facility containing weight training equipment"]}', NULL, 'spend time in the weight room / weight room session / weight room workout', '[{"en":"He spent two hours in the weight room before practice each morning.","zh-TW":"他每天早上訓練前在重量訓練室訓練了兩個小時。"},{"en":"The new weight room was equipped with both free weights and resistance machines.","zh-TW":"新的重量訓練室配備了自由重量器材和阻力機器。"}]', NULL, NULL, 4, 7012, NULL),
(7013, 'weighted average', '/ˈweɪtɪd ˈævərɪdʒ/', 'noun', '{"zh-TW":["加權平均"],"en":["an average where different values are given different levels of importance"]}', NULL, 'calculate weighted average / weighted average cost', '[{"en":"Weighted average cost of capital reflects both debt and equity costs.","zh-TW":"加權平均資本成本反映了債務和股本成本。"},{"en":"The portfolio return was calculated as a weighted average across all holdings.","zh-TW":"投資組合回報按所有持倉的加權平均計算。"}]', '{"abbreviation":"WACC for capital cost"}', NULL, 5, 7013, NULL),
(7014, 'weighted average cost of capital', '/ˈweɪtɪd ˈævərɪdʒ kɒst əv ˈkæpɪtl/', 'noun', '{"zh-TW":["加權平均資本成本"],"en":["the average rate a company pays to finance its assets from all sources"]}', NULL, 'calculate weighted average cost of capital / above the WACC', '[{"en":"Projects must exceed the weighted average cost of capital to create value.","zh-TW":"項目必須超過加權平均資本成本才能創造價值。"},{"en":"The WACC is used as the discount rate in DCF valuations.","zh-TW":"加權平均資本成本用作折現現金流估值中的折現率。"}]', '{"abbreviation":"WACC"}', NULL, 5, 7014, NULL),
(7015, 'weightlifting', '/''weɪtˌlɪftɪŋ/', 'noun', '{"zh-TW":["舉重；重量訓練"],"en":["the sport or activity of lifting barbells or other heavy weights as an exercise or in competition"]}', NULL, 'train in weightlifting / weightlifting competition / weightlifting record', '[{"en":"She took up weightlifting to build muscle strength and improve bone density.","zh-TW":"她開始舉重訓練以增強肌肉力量並改善骨密度。"},{"en":"Proper form is essential in weightlifting to prevent serious injuries.","zh-TW":"正確的姿勢在舉重中是必不可少的，以防止嚴重受傷。"}]', '{"verb":"weightlift","noun":"weightlifter"}', NULL, 5, 7015, NULL),
(7016, 'welfare', '/ˈwelfer/', 'noun', '{"zh-TW":["福利；福祉"],"en":["the health and happiness of a person or group"]}', NULL, 'employee welfare / social welfare / welfare benefits', '[{"en":"Employee welfare is a top priority for the company.","zh-TW":"員工福利是公司的首要任務。"},{"en":"The government increased social welfare spending.","zh-TW":"政府增加了社會福利支出。"}]', '{"noun":"welfare"}', NULL, 3, 7016, 486),
(7017, 'welfare economics', '/ˈwelfeər ˌiːkəˈnɒmɪks/', 'noun', '{"zh-TW":["福利經濟學"],"en":["the branch of economics that deals with the economic well-being of individuals and society"]}', NULL, 'study welfare economics / tools of welfare economics / applied welfare economics', '[{"en":"Welfare economics uses concepts such as efficiency and equity to evaluate policy outcomes.","zh-TW":"福利經濟學使用效率和公平等概念來評估政策結果。"},{"en":"Cost-benefit analysis is a key tool in applied welfare economics.","zh-TW":"成本效益分析是應用福利經濟學的關鍵工具。"}]', NULL, NULL, 5, 7017, NULL),
(7018, 'welfare state', '/ˈwelfɛər steɪt/', 'noun', '{"zh-TW":["福利國家"],"en":["a government system providing social protection to its citizens"]}', NULL, 'build a welfare state / welfare state reform / sustainable welfare state', '[{"en":"The welfare state provides a safety net for vulnerable populations.","zh-TW":"福利國家為弱勢族群提供安全網。"},{"en":"Aging populations are straining welfare state budgets across Europe.","zh-TW":"人口老齡化正在加重歐洲各地福利國家預算的壓力。"}]', NULL, NULL, 5, 7018, NULL),
(7019, 'well', '/wel/', 'verb, noun, adverb, adjective', '{"zh-TW":["【主要意義-副詞】好地；充分地","【次要意義-動詞】噴湧；湧出（情緒/液體）","【次要意義-名詞】水井；油井"],"en":["[primary - adverb] in a good or satisfactory way","[secondary - verb] to flow upward or outward like water from a spring","[secondary - noun] a hole drilled to obtain water or oil"]}', NULL, 'well up / tears welled / well of emotion / oil well', '[{"en":"Tears welled up in her eyes when she heard the news.","zh-TW":"當她聽到這個消息時，淚水湧上了她的眼眶。"},{"en":"Oil wells in the region produce over a million barrels per day.","zh-TW":"該地區的油井每天生產超過百萬桶石油。"},{"en":"A sense of pride welled up within the team after the successful launch.","zh-TW":"成功發布後，整個團隊湧現出一種自豪感。"}]', NULL, '動詞 well up 意為「（情緒）湧現；（液體）湧出」，名詞 well = 「水井/油井」，這兩種次要用法常見於 TOEIC 閱讀的能源或情感描述語境。', 1, 7019, NULL),
(7020, 'well-established', 'wɛl ɪˈstæblɪʃt', 'adjective', '{"zh-TW":["成熟的；成立已久的","信譽好的"],"en":["having been in existence for long","having a good reputation"]}', NULL, 'well-established company/well-established brand', '[{"en":"We are a well-established company in Taiwan.","zh-TW":"我們是台灣一家成立已久的公司。"}]', NULL, NULL, 5, 7020, NULL),
(7021, 'wellness center', '/ˈwɛlnɪs ˈsɛntər/', 'noun', '{"zh-TW":["健康中心"],"en":["a facility offering health and beauty treatments"]}', NULL, 'use the wellness center / wellness center services', '[{"en":"The resort''s wellness center offers yoga and meditation.","zh-TW":"度假村的健康中心提供瑜伽和冥想課程。"},{"en":"Book a treatment at the wellness center in advance.","zh-TW":"請提前預訂健康中心的療程。"}]', NULL, NULL, 5, 7021, NULL),
(7022, 'wellness program', '/ˈwɛlnɪs ˈprəʊɡræm/', 'noun', '{"zh-TW":["健康促進計劃"],"en":["a program aimed at promoting good health habits"]}', NULL, 'corporate wellness program / join a wellness program', '[{"en":"The company offers a wellness program including gym membership.","zh-TW":"公司提供包含健身房會員的健康促進計劃。"},{"en":"Participating in the wellness program reduces insurance premiums.","zh-TW":"參與健康促進計劃可降低保險費。"}]', NULL, NULL, 5, 7022, NULL),
(7023, 'wetland', '/ˈwetlænd/', 'noun', '{"zh-TW":["濕地"],"en":["land saturated with water, supporting unique plants and animals"]}', NULL, 'wetland conservation / wetland restoration / coastal wetland', '[{"en":"Wetlands provide natural flood protection and filter water pollutants.","zh-TW":"濕地提供天然防洪保護並過濾水污染物。"},{"en":"Many wetland areas have been drained for agricultural development.","zh-TW":"許多濕地地區已被排乾以用於農業開發。"}]', '{"adjective":"wetland"}', NULL, 3, 7023, NULL),
(7024, 'whereas', '/werˈæz/', 'conjunction', '{"zh-TW":["然而；反之"],"en":["in contrast to the fact that"]}', NULL, 'whereas in fact / whereas previously', '[{"en":"Sales increased in Asia, whereas they declined in Europe.","zh-TW":"銷售在亞洲增長，而在歐洲則下降。"},{"en":"The old system was manual, whereas the new one is automated.","zh-TW":"舊系統是手動的，而新系統是自動化的。"}]', NULL, NULL, 3, 7024, NULL),
(7025, 'whisk', '/''wɪsk/', 'verb', '{"zh-TW":["攪打；快速混合"],"en":["to beat or stir vigorously using a whisk or fork to incorporate air"]}', NULL, 'whisk together / whisk until smooth / whisk the eggs', '[{"en":"Whisk the eggs and sugar together until the mixture turns pale and fluffy.","zh-TW":"將雞蛋和糖一起攪打，直到混合物變得淡白而蓬鬆。"},{"en":"She whisked the cream into stiff peaks for the dessert topping.","zh-TW":"她將奶油攪打成硬性發泡，用作甜點的頂料。"}]', '{"noun":"whisk"}', NULL, 2, 7025, NULL),
(7026, 'whistleblower', '/ˈwɪslˌbloʊər/', 'noun', '{"zh-TW":["吹哨人；舉報人"],"en":["a person who reports illegal or unethical activity within an organization"]}', NULL, 'protect whistleblowers / whistleblower policy / whistleblower complaint', '[{"en":"The whistleblower exposed the company''s fraudulent accounting.","zh-TW":"吹哨人揭露了公司的欺詐性會計行為。"},{"en":"Whistleblower protections are essential for corporate accountability.","zh-TW":"吹哨人保護對公司問責至關重要。"}]', '{"verb":"blow the whistle"}', NULL, 5, 7026, NULL),
(7027, 'whistleblower protection', '/ˈwɪsəlbləʊər prəˈtekʃən/', 'noun', '{"zh-TW":["吹哨人保護"],"en":["legal safeguards for employees who report corporate wrongdoing"]}', NULL, 'provide whistleblower protection / whistleblower protection law / strengthen whistleblower protection', '[{"en":"Strong whistleblower protection laws encourage reporting of financial fraud.","zh-TW":"強有力的吹哨人保護法促進了財務欺詐的舉報。"},{"en":"The employee claimed the company retaliated against him in violation of whistleblower protection.","zh-TW":"員工聲稱公司違反吹哨人保護對他進行了報復。"}]', NULL, NULL, 5, 7027, NULL),
(7028, 'whistleblowing', '/ˈwɪsəlˌbləʊɪŋ/', 'noun', '{"zh-TW":["告發；揭弊"],"en":["the act of exposing illegal or unethical practices within an organization"]}', NULL, 'encourage whistleblowing / whistleblowing policy / protect whistleblowing', '[{"en":"Effective whistleblowing policies protect employees who report misconduct from retaliation.","zh-TW":"有效的揭弊政策保護舉報不當行為的員工免遭報復。"},{"en":"Whistleblowing by an accountant revealed the company''s accounting fraud.","zh-TW":"一位會計師的揭弊行為揭露了公司的會計欺詐。"}]', '{"noun2":"whistleblower","verb":"blow the whistle"}', NULL, 5, 7028, NULL),
(7029, 'white label', '/waɪt ˈleɪbəl/', 'noun', '{"zh-TW":["白標；貼牌"],"en":["a product made by one company but sold under another company brand"]}', NULL, 'white label product / white label service / white label solution', '[{"en":"The retailer sells white label products under its own brand name.","zh-TW":"零售商以自己的品牌名稱出售白標產品。"},{"en":"White label banking services allow fintech startups to launch quickly.","zh-TW":"白標銀行服務允許金融科技新創公司快速推出服務。"}]', '{"adjective":"white-label"}', NULL, 4, 7029, NULL),
(7030, 'white paper', '/waɪt ˈpeɪpər/', 'noun', '{"zh-TW":["白皮書"],"en":["an authoritative report or guide on a specific topic by an organization"]}', NULL, 'publish a white paper / technical white paper', '[{"en":"The company published a white paper on AI in supply chain management.","zh-TW":"公司發布了一份關於人工智慧在供應鏈管理中的白皮書。"},{"en":"A white paper establishes thought leadership and educates potential clients.","zh-TW":"白皮書確立了思想領導地位並教育了潛在客戶。"}]', NULL, NULL, 4, 7030, NULL),
(7031, 'white-collar', '/waɪt ˈkɒlər/', 'adjective', '{"zh-TW":["白領的；辦公室工作的"],"en":["relating to professional, managerial, or administrative work in an office"]}', NULL, 'white-collar worker / white-collar crime / white-collar profession', '[{"en":"The company employs mostly white-collar workers in its headquarters.","zh-TW":"公司總部主要聘用白領工作人員。"},{"en":"White-collar crime such as fraud has increased with digital transactions.","zh-TW":"隨著數位交易的發展，詐欺等白領犯罪有所增加。"}]', '{"opposite":"blue-collar"}', NULL, 4, 7031, NULL),
(7032, 'white-collar crime', '/ˌwaɪt ˈkɒlər kraɪm/', 'noun', '{"zh-TW":["白領犯罪"],"en":["non-violent crimes committed by business professionals for financial gain"]}', NULL, 'investigate white-collar crime / prosecute white-collar crime / white-collar crime case', '[{"en":"White-collar crime such as insider trading and embezzlement causes significant economic harm.","zh-TW":"內幕交易和挪用公款等白領犯罪造成重大經濟損失。"},{"en":"Regulators increased penalties to deter white-collar crime in the financial sector.","zh-TW":"監管機構加重懲罰以阻嚇金融領域的白領犯罪。"}]', NULL, NULL, 5, 7032, NULL),
(7033, 'whiteboard', '/ˈwaɪtbɔːrd/', 'noun', '{"zh-TW":["白板"],"en":["a smooth white board used for writing in meetings"]}', NULL, 'use a whiteboard / digital whiteboard', '[{"en":"The trainer drew diagrams on the whiteboard.","zh-TW":"培訓師在白板上畫了圖表。"},{"en":"Virtual whiteboards allow remote teams to collaborate visually.","zh-TW":"虛擬白板使遠端團隊能夠進行視覺協作。"}]', NULL, NULL, 4, 7033, NULL),
(7034, 'whole', 'hoʊl', 'adjective', '{"zh-TW":["整體的；全部的","完整的"],"en":["complete, not divided","all of something"]}', NULL, 'whole team/whole process', '[{"en":"The whole team contributed to the success.","zh-TW":"整個團隊為成功做出了貢獻。"}]', '{"noun":"whole","adverb":"wholly"}', NULL, 2, 7034, NULL),
(7035, 'wholesale', '/ˈhoʊlseɪl/', 'noun', '{"zh-TW":["批發","批發的"],"en":["the selling of goods in large quantities at low prices","the selling of goods in large quantities","on a large scale"]}', '{"root":{"text":"whole","meaning":"whole (整體)"},"suffix":{"text":"sale","meaning":"sale (銷售)"},"logic":"整批銷售，即「批發」。"}', 'wholesale price / wholesale market; wholesale price / wholesale market / wholesale distributor', '[{"en":"They buy wholesale and sell retail.","zh-TW":"他們批發購入，零售賣出。"},{"en":"The wholesale price is much lower.","zh-TW":"批發價便宜很多。"},{"en":"We buy materials at wholesale prices.","zh-TW":"我們以批發價購買材料。"},{"en":"The wholesale market opens at 5 AM.","zh-TW":"批發市場凌晨5點開門。"}]', '{"noun":"wholesaler","adjective":"wholesale"}', NULL, 3, 7035, NULL),
(7036, 'wholesale price', '/ˈhoʊlseɪl praɪs/', 'noun', '{"zh-TW":["批發價格"],"en":["the price at which goods are sold in large quantities to retailers"]}', NULL, 'negotiate wholesale price / wholesale price index', '[{"en":"Retailers buy at wholesale prices and sell at retail prices.","zh-TW":"零售商以批發價購買並以零售價出售。"},{"en":"A reduction in wholesale prices helped retailers improve margins.","zh-TW":"批發價格的降低幫助零售商提高了利潤率。"}]', NULL, NULL, 5, 7036, NULL),
(7037, 'wholesome', '/''həʊlsəm/', 'adjective', '{"zh-TW":["有益健康的；滋養的"],"en":["conducive to health or well-being; nourishing and natural"]}', NULL, 'wholesome meal / wholesome diet / wholesome ingredients', '[{"en":"She prepared a wholesome meal of grilled fish, brown rice, and steamed vegetables.","zh-TW":"她準備了一頓健康的餐食，包括烤魚、糙米和清蒸蔬菜。"},{"en":"The café attracted health-conscious customers with its wholesome menu.","zh-TW":"這家咖啡館以其健康菜單吸引了注重健康的顧客。"}]', '{"noun":"wholesomeness"}', NULL, 3, 7037, NULL),
(7038, 'wide', 'waɪd', 'adjective', '{"zh-TW":["寬廣的；廣泛的","大量的"],"en":["covering a large area or range","extensive"]}', NULL, 'wide range/wide variety', '[{"en":"We offer a wide range of products.","zh-TW":"我們提供廣泛的產品系列。"}]', '{"noun":"width","adverb":"widely"}', NULL, 1, 7038, NULL),
(7039, 'widen', '/ˈwaɪdn/', 'verb', '{"zh-TW":["加寬；擴大"],"en":["to make or become wider or more extensive"]}', NULL, 'widen the gap / widen the scope / widen access', '[{"en":"The gap between rich and poor continues to widen.","zh-TW":"貧富差距持續擴大。"},{"en":"We plan to widen the scope of our services.","zh-TW":"我們計劃擴大服務範圍。"}]', '{"noun":"width","verb":"widen","adjective":"wide"}', NULL, 2, 7039, NULL),
(7040, 'widespread', '/ˈwaɪdspred/', 'adjective', '{"zh-TW":["普遍的；廣泛的"],"en":["found or distributed over a large area"]}', NULL, 'widespread use / widespread concern / widespread adoption', '[{"en":"There is widespread concern about data privacy.","zh-TW":"人們普遍關注資料隱私問題。"},{"en":"The technology has gained widespread adoption.","zh-TW":"這項技術已被廣泛採用。"}]', '{"adjective":"widespread"}', NULL, 4, 7040, NULL),
(7041, 'wildfire', '/ˈwaɪldfaɪər/', 'noun', '{"zh-TW":["野火；山火"],"en":["an uncontrolled fire spreading rapidly through vegetation"]}', NULL, 'contain a wildfire / wildfire risk', '[{"en":"The wildfire destroyed thousands of acres of forest.","zh-TW":"野火摧毀了數千英畝的森林。"},{"en":"Climate change increases the frequency and intensity of wildfires.","zh-TW":"氣候變遷增加了野火的頻率和強度。"}]', NULL, NULL, 3, 7041, NULL),
(7042, 'willing', '/ˈwɪlɪŋ/', 'adjective', '{"zh-TW":["願意的；樂意的"],"en":["ready or eager to do something"]}', NULL, 'willing to / willing participant / willing and able', '[{"en":"Are you willing to relocate for the job?","zh-TW":"你願意為這份工作搬遷嗎？"},{"en":"We need willing participants for the pilot program.","zh-TW":"我們需要願意參加試驗計畫的人。"}]', '{"noun":"willingness","adjective":"willing, unwilling","adverb":"willingly"}', NULL, 3, 7042, NULL),
(7043, 'wind', '/wɪnd/', 'noun', '{"zh-TW":["風"],"en":["moving air"]}', '{"root":{"text":"wind","meaning":"blow (吹)"},"logic":"空氣的流動。"}', 'strong wind / wind speed / wind power', '[{"en":"The wind blew the leaves off the trees.","zh-TW":"風把樹葉從樹上吹落。"},{"en":"Wind power is a renewable energy source.","zh-TW":"風力是一種再生能源。"}]', '{"adjective":"windy"}', NULL, 1, 7043, NULL),
(7044, 'wind energy', '/wɪnd ˈɛnərdʒi/', 'noun', '{"zh-TW":["風能"],"en":["energy from wind converted into electricity"]}', NULL, 'harness wind energy / wind energy farm', '[{"en":"Wind energy is one of the fastest-growing energy sources.","zh-TW":"風能是增長最快的能源之一。"},{"en":"The offshore wind energy farm supplies power to 100,000 homes.","zh-TW":"離岸風力發電場為10萬戶家庭供電。"}]', NULL, NULL, 4, 7044, NULL),
(7045, 'window dressing', '/ˈwɪndoʊ ˈdresɪŋ/', 'noun', '{"zh-TW":["表面文章；橱窗裝飾"],"en":["the practice of making a company''s finances appear better than they actually are"]}', NULL, 'avoid window dressing / window dressing of accounts', '[{"en":"Some companies engage in window dressing before the annual report deadline.","zh-TW":"某些公司在年報截止日期前進行表面文章。"},{"en":"Window dressing distorts the true picture of a company''s financial health.","zh-TW":"表面文章歪曲了公司財務狀況的真實面貌。"}]', NULL, NULL, 5, 7045, NULL),
(7046, 'window of opportunity', '/ˈwɪndoʊ əv ˌɒpərˈtjuːnɪti/', 'noun', '{"zh-TW":["機會之窗；有利時機"],"en":["a brief period during which an action can be taken successfully"]}', NULL, 'identify a window of opportunity / act within the window of opportunity', '[{"en":"A window of opportunity exists before the competitor launches next month.","zh-TW":"在競爭對手下月推出產品之前存在一個機會之窗。"},{"en":"The company acted quickly to seize the window of opportunity.","zh-TW":"公司迅速行動以抓住機會之窗。"}]', NULL, NULL, 5, 7046, NULL),
(7047, 'window seat', '/ˈwɪndoʊ siːt/', 'noun', '{"zh-TW":["靠窗座位"],"en":["a seat next to the window in a plane"]}', NULL, 'request a window seat / enjoy the view from the window seat', '[{"en":"She chose a window seat to enjoy the view.","zh-TW":"她選擇靠窗座位以欣賞風景。"},{"en":"A window seat is great for sleeping on long flights.","zh-TW":"靠窗座位適合在長途飛行中睡覺。"}]', NULL, NULL, 4, 7047, NULL),
(7048, 'wine list', '/waɪn lɪst/', 'noun', '{"zh-TW":["酒單"],"en":["a list of wines available at a restaurant"]}', NULL, 'browse the wine list / extensive wine list', '[{"en":"The sommelier helped us choose from the wine list.","zh-TW":"侍酒師幫助我們從酒單中選擇。"},{"en":"Their wine list features bottles from around the world.","zh-TW":"他們的酒單有來自世界各地的酒款。"}]', NULL, NULL, 3, 7048, NULL),
(7049, 'wine pairing', '/waɪn ˈpɛərɪŋ/', 'noun', '{"zh-TW":["餐酒搭配"],"en":["the matching of wine to food for a better dining experience"]}', NULL, 'wine pairing suggestion / wine pairing menu', '[{"en":"The sommelier offered wine pairing suggestions with each course.","zh-TW":"侍酒師為每道菜提供了餐酒搭配建議。"},{"en":"Good wine pairing enhances both the food and the wine.","zh-TW":"良好的餐酒搭配同時提升了食物和葡萄酒的風味。"}]', NULL, NULL, 4, 7049, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(7050, 'winning streak', '/''wɪnɪŋ striːk/', 'noun', '{"zh-TW":["連勝；連贏"],"en":["a series of consecutive wins by a person or team"]}', NULL, 'extend a winning streak / end a winning streak / impressive winning streak', '[{"en":"The team''s impressive winning streak of twelve games came to an end last night.","zh-TW":"球隊令人印象深刻的十二場連勝昨晚宣告結束。"},{"en":"She was on a winning streak, winning every tournament she entered.","zh-TW":"她正處於連勝狀態，贏得了她參加的每一個比賽。"}]', NULL, NULL, 5, 7050, NULL),
(7051, 'wire transfer', '/ˈwaɪər ˈtrænsfɜːr/', 'noun', '{"zh-TW":["電匯；電子匯款"],"en":["an electronic transfer of funds between banks"]}', NULL, 'send a wire transfer / international wire transfer', '[{"en":"The company sent a wire transfer to pay the foreign supplier.","zh-TW":"公司發送了電匯支付給外國供應商。"},{"en":"Wire transfers usually arrive within one to two business days.","zh-TW":"電匯通常在一到兩個工作日內到達。"}]', NULL, NULL, 5, 7051, NULL),
(7052, 'wireless', '/ˈwaɪərlɪs/', 'adjective', '{"zh-TW":["無線的"],"en":["using radio signals instead of wires"]}', NULL, 'wireless network / wireless charging', '[{"en":"The hotel has free wireless internet.","zh-TW":"飯店有免費無線網路。"},{"en":"This phone supports wireless charging.","zh-TW":"這支手機支援無線充電。"}]', NULL, NULL, 3, 7052, NULL),
(7053, 'withdraw', '/wɪðˈdrɔː/', 'verb', '{"zh-TW":["撤回；提款","退出"],"en":["to take back; to remove money from a bank","to leave or pull out"]}', NULL, 'withdraw funds / withdraw from / withdraw support', '[{"en":"The investor withdrew funding from the project.","zh-TW":"投資者從專案中撤回了資金。"},{"en":"She withdrew her application for the position.","zh-TW":"她撤回了該職位的申請。"}]', '{"noun":"withdrawal","verb":"withdraw"}', NULL, 3, 7053, NULL),
(7054, 'withdrawal', 'wɪðˈdrɔːəl', 'noun', '{"zh-TW":["撤回；提款","退出"],"en":["the act of taking back","removing money from an account"]}', NULL, 'cash withdrawal/contract withdrawal', '[{"en":"Please process the withdrawal request.","zh-TW":"請處理提款申請。"}]', '{"verb":"withdraw","adjective":"withdrawn"}', NULL, 4, 7054, 487),
(7055, 'withhold', '/wɪðˈhoʊld/', 'verb', '{"zh-TW":["扣留；隱瞞"],"en":["to hold back; to refrain from giving"]}', NULL, 'withhold information / withhold payment / withhold tax', '[{"en":"The company withheld the bonus due to poor performance.","zh-TW":"公司因業績不佳而扣留了獎金。"},{"en":"Employers must withhold income tax from wages.","zh-TW":"雇主必須從薪資中預扣所得稅。"}]', '{"noun":"withholding","verb":"withhold"}', NULL, 3, 7055, NULL),
(7056, 'withholding tax', '/wɪðˈhoʊldɪŋ tæks/', 'noun', '{"zh-TW":["預扣稅；扣繳稅款"],"en":["a tax deducted at source from payments such as dividends, interest, or wages"]}', NULL, 'apply withholding tax / withholding tax rate', '[{"en":"Dividends paid to non-residents are subject to withholding tax.","zh-TW":"支付給非居民的股息須繳納預扣稅。"},{"en":"The withholding tax rate on interest payments is 15%.","zh-TW":"利息付款的預扣稅率為15%。"}]', NULL, NULL, 5, 7056, NULL),
(7057, 'withstand', '/wɪðˈstænd/', 'verb', '{"zh-TW":["承受；抵抗"],"en":["to remain undamaged by; to resist"]}', NULL, 'withstand pressure / withstand competition / withstand scrutiny', '[{"en":"The company withstood intense market competition.","zh-TW":"公司經受住了激烈的市場競爭。"},{"en":"The product is designed to withstand extreme conditions.","zh-TW":"該產品設計為可承受極端條件。"}]', '{"verb":"withstand"}', NULL, 3, 7057, NULL),
(7058, 'witness', '/ˈwɪtnəs/', 'noun, verb', '{"zh-TW":["目擊者；證人","目睹；見證"],"en":["a person who sees an event","to see something happen"]}', NULL, 'witness growth / bear witness / expert witness', '[{"en":"The industry witnessed rapid growth last year.","zh-TW":"該行業去年見證了快速增長。"},{"en":"We are witnessing a major shift in consumer behavior.","zh-TW":"我們正在見證消費者行為的重大轉變。"}]', '{"noun":"witness","verb":"witness"}', NULL, 3, 7058, NULL),
(7059, 'work', 'wɜːrk', 'verb', '{"zh-TW":["工作；運作","有效"],"en":["to do a job","to function correctly"]}', NULL, 'work on/together/remotely', '[{"en":"The team works remotely on Fridays.","zh-TW":"團隊週五遠程工作。"}]', '{"noun":"work, worker","adjective":"working","adverb":"workably"}', NULL, 1, 7059, NULL),
(7060, 'work breakdown structure', '/wɜːrk ˈbreɪkdaʊn ˈstrʌktʃər/', 'noun', '{"zh-TW":["工作分解結構"],"en":["a hierarchical decomposition of the total project work into components"]}', NULL, 'create a work breakdown structure / define the work breakdown structure', '[{"en":"The work breakdown structure was used to assign tasks and estimate costs.","zh-TW":"工作分解結構用於分配任務和估算成本。"},{"en":"A detailed work breakdown structure improves project planning accuracy.","zh-TW":"詳細的工作分解結構提高了項目計劃的準確性。"}]', '{"abbreviation":"WBS"}', NULL, 5, 7060, NULL),
(7061, 'work ethic', '/wɜːrk ˈeθɪk/', 'noun', '{"zh-TW":["工作倫理；敬業精神"],"en":["a set of values based on hard work and diligence in one''s job"]}', NULL, 'strong work ethic / demonstrate work ethic / professional work ethic', '[{"en":"Her strong work ethic was recognized at the performance review.","zh-TW":"她強烈的敬業精神在績效評估中得到了認可。"},{"en":"A strong work ethic is one of the most sought-after qualities in candidates.","zh-TW":"強烈的敬業精神是候選人最受歡迎的品質之一。"}]', NULL, NULL, 4, 7061, NULL),
(7062, 'work-life balance', '/wɜːrk laɪf ˈbæləns/', 'noun', '{"zh-TW":["工作與生活平衡"],"en":["achieving a healthy balance between professional and personal life"]}', NULL, 'improve work-life balance / achieve work-life balance / work-life balance policy', '[{"en":"Flexible hours help employees maintain a healthy work-life balance.","zh-TW":"彈性工時幫助員工保持健康的工作與生活平衡。"},{"en":"Poor work-life balance leads to burnout and high turnover.","zh-TW":"工作與生活失衡導致職業倦怠和高流動率。"}]', NULL, NULL, 5, 7062, NULL),
(7063, 'work-life integration', '/''wɜːrk laɪf ˌɪntɪˌɡreɪʃən/', 'noun', '{"zh-TW":["工作與生活整合"],"en":["an approach to balancing professional and personal life by blending the two more fluidly"]}', NULL, 'achieve work-life integration / work-life integration strategy / benefit of work-life integration', '[{"en":"She sought work-life integration rather than strict separation between her career and family time.","zh-TW":"她尋求工作與生活整合，而不是職業與家庭時間之間的嚴格分隔。"},{"en":"Technology has made work-life integration both easier and more challenging simultaneously.","zh-TW":"技術使工作與生活整合同時變得更容易也更具挑戰性。"}]', '{"noun":"integration"}', NULL, 5, 7063, NULL),
(7064, 'workaround', '/''wɜːrkəˌraʊnd/', 'noun', '{"zh-TW":["變通方法；臨時解決方案"],"en":["a method for circumventing a problem or limitation when a direct solution is unavailable"]}', NULL, 'find a workaround / use a workaround / develop a workaround', '[{"en":"The IT team found a temporary workaround while the system was being repaired.","zh-TW":"IT團隊在系統修復期間找到了臨時變通方法。"},{"en":"A quick workaround was implemented to keep operations running until the update was released.","zh-TW":"在更新發布之前，實施了一個快速的臨時解決方案以保持業務運行。"}]', '{"verb":"work around"}', NULL, 4, 7064, NULL),
(7065, 'workflow', '/ˈwɜːrkfloʊ/', 'noun', '{"zh-TW":["工作流程"],"en":["the sequence of steps in a business process"]}', NULL, 'optimize workflow / workflow management / automate workflow', '[{"en":"Automating the workflow saved hours of manual work each week.","zh-TW":"自動化工作流程每週節省了數小時的手動工作。"},{"en":"The new software streamlined our approval workflow.","zh-TW":"新軟體簡化了我們的審批工作流程。"}]', '{"verb":"workflow"}', NULL, 3, 7065, 949),
(7066, 'workforce', '/ˈwɜːrkfɔːrs/', 'noun', '{"zh-TW":["勞動力；員工總數"],"en":["the people engaged in work"]}', NULL, 'skilled workforce / workforce development / reduce the workforce', '[{"en":"The company has a workforce of 5,000 employees.","zh-TW":"公司擁有5000名員工。"},{"en":"Investing in workforce development is essential.","zh-TW":"投資勞動力發展至關重要。"}]', '{"noun":"workforce, work, worker"}', NULL, 3, 7066, NULL),
(7067, 'workforce development', '/ˈwɜːrkfɔːrs dɪˈveləpmənt/', 'noun', '{"zh-TW":["人才培育；勞動力發展"],"en":["the process of improving workers'' skills and creating employment opportunities"]}', NULL, 'invest in workforce development / workforce development program / national workforce development', '[{"en":"Workforce development programs help workers adapt to technological change.","zh-TW":"人才培育計畫幫助工人適應技術變革。"},{"en":"Effective workforce development requires collaboration between government and industry.","zh-TW":"有效的勞動力發展需要政府和工業界的合作。"}]', NULL, NULL, 5, 7067, NULL),
(7068, 'workforce planning', '/ˈwɜːrkfɔːrs ˈplænɪŋ/', 'noun', '{"zh-TW":["人力規劃"],"en":["aligning a company''s staffing needs with its strategic goals"]}', NULL, 'strategic workforce planning / workforce planning model', '[{"en":"Workforce planning identified a skills gap in the engineering team.","zh-TW":"人力規劃發現了工程團隊的技能缺口。"},{"en":"Effective workforce planning reduces unexpected staffing shortages.","zh-TW":"有效的人力規劃減少了意外的人員短缺。"}]', NULL, NULL, 5, 7068, NULL),
(7069, 'working capital', '/ˈwɜːrkɪŋ ˈkæpɪtl/', 'noun', '{"zh-TW":["營運資金；流動資金"],"en":["current assets minus current liabilities; funds available for day-to-day operations"]}', NULL, 'working capital management / positive working capital', '[{"en":"The company needs more working capital to fund operations.","zh-TW":"公司需要更多營運資金來支持運營。"},{"en":"Efficient inventory control improves working capital.","zh-TW":"有效的庫存控制改善了營運資金。"}]', NULL, NULL, 5, 7069, NULL),
(7070, 'working capital cycle', '/ˈwɜːrkɪŋ ˈkæpɪtəl ˈsaɪkəl/', 'noun', '{"zh-TW":["營運資金週期"],"en":["the time taken to convert working capital into cash through operations"]}', NULL, 'shorten the working capital cycle / manage working capital cycle / optimize the cycle', '[{"en":"Efficient inventory management shortens the working capital cycle.","zh-TW":"有效的庫存管理縮短了營運資金週期。"},{"en":"A longer working capital cycle ties up cash and reduces liquidity.","zh-TW":"更長的營運資金週期佔用現金並降低流動性。"}]', NULL, NULL, 5, 7070, NULL),
(7071, 'working capital management', '/ˈwɜːrkɪŋ ˈkæpɪtl ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["營運資金管理"],"en":["managing short-term assets and liabilities to ensure operational efficiency"]}', NULL, 'improve working capital management / working capital management strategy', '[{"en":"Effective working capital management prevents cash flow crises.","zh-TW":"有效的營運資金管理可防止現金流危機。"},{"en":"Inventory optimization is a core part of working capital management.","zh-TW":"庫存優化是營運資金管理的核心部分。"}]', NULL, NULL, 5, 7071, NULL),
(7072, 'working capital ratio', '/ˈwɜːrkɪŋ ˈkæpɪtəl ˈreɪʃioʊ/', 'noun', '{"zh-TW":["營運資金比率"],"en":["a ratio comparing current assets to current liabilities to assess short-term health"]}', NULL, 'calculate working capital ratio / improve working capital ratio', '[{"en":"A working capital ratio above 1 indicates the company can cover short-term debt.","zh-TW":"高於1的營運資金比率表明公司可以償還短期債務。"},{"en":"The CFO monitored the working capital ratio to manage liquidity risk.","zh-TW":"財務長監控營運資金比率以管理流動性風險。"}]', NULL, NULL, 5, 7072, NULL),
(7073, 'working group', '/ˈwɜːrkɪŋ ɡruːp/', 'noun', '{"zh-TW":["工作組"],"en":["a group of people working together to achieve a specific objective"]}', NULL, 'working group meeting / join a working group / working group recommendations', '[{"en":"The working group developed new data privacy guidelines.","zh-TW":"工作組制定了新的資料隱私指南。"},{"en":"Several working groups were formed to study the policy options.","zh-TW":"成立了幾個工作組研究政策選項。"}]', NULL, NULL, 5, 7073, NULL),
(7074, 'working hypothesis', '/ˈwɜːrkɪŋ haɪˈpɒθɪsɪs/', 'noun', '{"zh-TW":["工作假設"],"en":["a provisional hypothesis used as a basis for research"]}', NULL, 'develop a working hypothesis / test a working hypothesis / refine the working hypothesis', '[{"en":"The team began with a working hypothesis that was later confirmed by evidence.","zh-TW":"團隊從一個工作假設開始，後來被證據所證實。"},{"en":"A working hypothesis guides data collection and analysis in exploratory research.","zh-TW":"工作假設指導探索性研究中的數據收集和分析。"}]', NULL, NULL, 5, 7074, NULL),
(7075, 'working interest', '/ˈwɜːrkɪŋ ˈɪntrɪst/', 'noun', '{"zh-TW":["作業利益；工作利益"],"en":["an ownership interest in an oil or gas property entitling the holder to a share of production"]}', NULL, 'hold a working interest / working interest percentage', '[{"en":"The company sold its 30% working interest in the oil field.","zh-TW":"公司出售了其在油田中30%的作業利益。"},{"en":"A working interest holder bears both the costs and benefits of production.","zh-TW":"作業利益持有人承擔生產的成本和收益。"}]', NULL, NULL, 5, 7075, NULL),
(7076, 'working remotely', '/ˈwɜːrkɪŋ rɪˈmoʊtli/', 'verb', '{"zh-TW":["遠程辦公；在家工作"],"en":["carrying out work duties from a location other than the office"]}', NULL, 'work remotely / working remotely options', '[{"en":"The team has been working remotely since the pandemic.","zh-TW":"自疫情以來，團隊一直在遠程辦公。"},{"en":"Working remotely requires strong self-discipline and clear communication.","zh-TW":"遠程辦公需要強大的自律和清晰的溝通。"}]', NULL, NULL, 5, 7076, NULL),
(7077, 'workload', '/ˈwɜːrkloʊd/', 'noun', '{"zh-TW":["工作量；工作負擔"],"en":["the amount of work assigned to or done by an employee or team"]}', NULL, 'manage workload / heavy workload / workload balance / workload distribution', '[{"en":"The new hire helped reduce the team''s heavy workload.","zh-TW":"新員工幫助減輕了團隊沉重的工作量。"},{"en":"Workload distribution must be fair to prevent employee burnout.","zh-TW":"工作量分配必須公平以防止員工倦怠。"}]', '{"adjective":"workload-intensive"}', NULL, 3, 7077, 488),
(7078, 'workload management', '/''wɜːrkˌləʊd ˌmænɪdʒmənt/', 'noun', '{"zh-TW":["工作量管理；任務管理"],"en":["the process of distributing and controlling tasks among employees to ensure efficiency and prevent burnout"]}', NULL, 'improve workload management / workload management tools / effective workload management', '[{"en":"Effective workload management prevents burnout and maintains team productivity.","zh-TW":"有效的工作量管理可以防止職業倦怠並維持團隊生產力。"},{"en":"She used project management software to improve workload management across her team.","zh-TW":"她使用項目管理軟體改善了整個團隊的工作量管理。"}]', NULL, NULL, 5, 7078, NULL),
(7079, 'workout routine', '/''wɜːrkˌaʊt ruːˌtiːn/', 'noun', '{"zh-TW":["鍛煉例程；運動計劃"],"en":["a regular program of physical exercise followed consistently"]}', NULL, 'follow a workout routine / establish a workout routine / daily workout routine', '[{"en":"Sticking to a workout routine helps build long-term fitness habits.","zh-TW":"堅持鍛煉例程有助於建立長期的健身習慣。"},{"en":"Her workout routine consists of strength training three days a week and running on alternate days.","zh-TW":"她的鍛煉例程包括每週三天的力量訓練和隔天跑步。"}]', '{"noun":"routine"}', NULL, 5, 7079, NULL),
(7080, 'workplace', 'ˈwɜːrkpleɪs', 'noun', '{"zh-TW":["工作場所；職場","辦公場所"],"en":["where people work","an office or factory"]}', NULL, 'safe workplace/workplace culture', '[{"en":"Maintaining a safe workplace is essential.","zh-TW":"維持安全的工作場所至關重要。"}]', '{"adjective":"workplace-based"}', NULL, 3, 7080, 243),
(7081, 'workplace injury', '/ˈwɜːrkpleɪs ˈɪndʒəri/', 'noun', '{"zh-TW":["工作場所傷害；職業傷害"],"en":["an injury sustained while performing work duties"]}', NULL, 'prevent workplace injuries / report a workplace injury', '[{"en":"All workplace injuries must be reported immediately.","zh-TW":"所有工作場所傷害必須立即報告。"},{"en":"The company implemented new procedures to reduce workplace injuries.","zh-TW":"公司實施了新程序以減少工作場所傷害。"}]', NULL, NULL, 5, 7081, NULL),
(7082, 'workshop', '/ˈwɜːrkʃɑːp/', 'noun', '{"zh-TW":["研討會；工作坊"],"en":["a meeting for discussion or practical work"]}', NULL, 'training workshop / conduct a workshop / hands-on workshop', '[{"en":"The HR department organized a leadership workshop.","zh-TW":"人資部門組織了一場領導力工作坊。"},{"en":"The workshop covered project management skills.","zh-TW":"工作坊涵蓋了專案管理技能。"}]', '{"noun":"workshop"}', NULL, 3, 7082, NULL),
(7083, 'world', 'wɜːrld', 'noun', '{"zh-TW":["世界；全球","領域"],"en":["the Earth and its people","a particular field"]}', NULL, 'global world/world market', '[{"en":"We operate in a competitive world market.","zh-TW":"我們在競爭激烈的全球市場中運營。"}]', '{"adjective":"worldwide, worldly","adverb":"worldwide"}', NULL, 2, 7083, NULL),
(7084, 'worldbuilding', '/ˈwɜːldbɪldɪŋ/', 'noun', '{"zh-TW":["世界觀構建；世界設定"],"en":["the process of creating an imaginary world for a story or game"]}', NULL, 'extensive worldbuilding / worldbuilding details / rich worldbuilding', '[{"en":"The fantasy series is admired for its detailed and immersive worldbuilding.","zh-TW":"這部奇幻系列因其詳細而沉浸式的世界觀構建而備受讚譽。"},{"en":"Good worldbuilding makes a fictional universe feel real and consistent.","zh-TW":"良好的世界觀構建使虛構的宇宙感覺真實且一致。"}]', NULL, NULL, 5, 7084, NULL),
(7085, 'worldwide', 'ˈwɜːrldwaɪd', 'adjective', '{"zh-TW":["全球的；世界性的","世界範圍的"],"en":["extending throughout the world","international"]}', NULL, 'worldwide distribution/worldwide recognition', '[{"en":"Our products have worldwide distribution.","zh-TW":"我們的產品在全球分銷。"}]', '{"adverb":"worldwide"}', NULL, 3, 7085, 489),
(7086, 'worth', '/wɜːrθ/', 'noun, adjective', '{"zh-TW":["價值","值得的"],"en":["the value of something","deserving of"]}', NULL, 'worth mentioning / net worth / worth the effort', '[{"en":"The investment is definitely worth the risk.","zh-TW":"這項投資絕對值得冒險。"},{"en":"The company''s net worth exceeded $1 billion.","zh-TW":"公司淨值超過了10億美元。"}]', '{"noun":"worth","adjective":"worth, worthy, worthwhile"}', NULL, 2, 7086, NULL),
(7087, 'worthwhile', '/ˌwɜːrθˈwaɪl/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["worth the time, money, or effort spent"]}', NULL, 'worthwhile investment / worthwhile endeavor / make it worthwhile', '[{"en":"The training program proved to be a worthwhile investment.","zh-TW":"培訓計畫被證明是一項值得的投資。"},{"en":"It''s worthwhile to compare prices before purchasing.","zh-TW":"購買前比較價格是值得的。"}]', '{"adjective":"worthwhile, worthy","noun":"worth"}', NULL, 4, 7087, NULL),
(7088, 'worthy', '/ˈwɜːrði/', 'adjective', '{"zh-TW":["值得的；有價值的"],"en":["deserving respect or attention"]}', NULL, 'worthy of / worthy cause / noteworthy', '[{"en":"The proposal is worthy of consideration.","zh-TW":"這個提案值得考慮。"},{"en":"They donated to a worthy cause.","zh-TW":"他們為一項有價值的事業捐款。"}]', '{"noun":"worth, worthiness","adjective":"worthy, unworthy, noteworthy"}', NULL, 2, 7088, NULL),
(7089, 'wrap', '/ræp/', 'noun', '{"zh-TW":["捲餅；包裹"],"en":["food wrapped in a flatbread or tortilla"]}', NULL, 'chicken wrap / veggie wrap', '[{"en":"She ordered a chicken wrap with a side salad.","zh-TW":"她點了一個雞肉捲餅配沙拉。"},{"en":"Wraps are a popular choice for a quick lunch.","zh-TW":"捲餅是快速午餐的熱門選擇。"}]', NULL, NULL, 1, 7089, NULL),
(7090, 'writ of execution', '/rɪt əv ˌeksɪˈkjuːʃən/', 'noun', '{"zh-TW":["執行令"],"en":["a court order directing that a judgment be enforced"]}', NULL, 'issue a writ of execution / obtain a writ of execution / enforce via writ of execution', '[{"en":"The creditor obtained a writ of execution to seize the debtor''s assets.","zh-TW":"債權人取得了執行令以扣押債務人的資產。"},{"en":"A writ of execution is the primary tool for enforcing money judgments.","zh-TW":"執行令是執行金錢判決的主要工具。"}]', NULL, NULL, 5, 7090, NULL),
(7091, 'write', 'raɪt', 'verb', '{"zh-TW":["書寫；撰寫","寫作"],"en":["to form letters or words","to compose"]}', NULL, 'write a report/email', '[{"en":"Please write a summary of the meeting.","zh-TW":"請撰寫會議摘要。"}]', '{"noun":"writing, writer","adjective":"written","adverb":"writely"}', NULL, 2, 7091, NULL),
(7092, 'write down', '/raɪt daʊn/', 'verb', '{"zh-TW":["減記；減值"],"en":["to reduce the recorded value of an asset"]}', NULL, 'write down an asset / write down inventory', '[{"en":"The company wrote down its goodwill by 30 million dollars.","zh-TW":"公司將商譽減記了3000萬元。"},{"en":"Inventory was written down after the market price fell below cost.","zh-TW":"市場價格跌破成本後，庫存被減記了。"}]', '{"noun":"write-down","adjective":"written down"}', NULL, 4, 7092, NULL),
(7093, 'write-down', '/ˈraɪt daʊn/', 'noun', '{"zh-TW":["資產減記"],"en":["a partial reduction in the book value of an asset that has decreased in value"]}', NULL, 'record a write-down / write-down of inventory', '[{"en":"A write-down of inventory was required after damaged goods were discovered.","zh-TW":"發現受損貨物後需要對庫存進行資產減記。"},{"en":"The write-down reduced the asset''s book value by 40%.","zh-TW":"資產減記將資產的帳面價值降低了40%。"}]', '{"verb":"write down"}', NULL, 4, 7093, NULL),
(7094, 'write-off', '/ˈraɪt ɒf/', 'noun', '{"zh-TW":["核銷；沖銷"],"en":["the removal of an uncollectable asset from the books"]}', NULL, 'write off a debt / tax write-off / bad debt write-off', '[{"en":"The company wrote off $5 million in uncollectable receivables.","zh-TW":"公司沖銷了500萬美元的無法收回應收帳款。"},{"en":"A write-off reduced taxable income for the year.","zh-TW":"核銷減少了當年的應稅收入。"}]', '{"verb":"write off"}', NULL, 3, 7094, NULL),
(7095, 'write-up', '/ˈraɪtʌp/', 'noun', '{"zh-TW":["書面報告；評論"],"en":["a written account or review of something"]}', NULL, 'prepare a write-up / formal write-up', '[{"en":"The journalist prepared a write-up of the product launch.","zh-TW":"記者準備了產品發布的書面報告。"},{"en":"Please submit a write-up of your project findings.","zh-TW":"請提交您的項目發現的書面報告。"}]', '{"verb":"write up"}', NULL, 3, 7095, NULL),
(7096, 'written', 'ˈrɪtən', 'adjective', '{"zh-TW":["書面的；成文的","文字的"],"en":["expressed in writing","documented"]}', NULL, 'written agreement/written confirmation', '[{"en":"Please provide written confirmation.","zh-TW":"請提供書面確認。"}]', '{"verb":"write","adverb":"in writing"}', NULL, 3, 7096, NULL),
(7097, 'written communication', '/''rɪtən kəˌmjuːnɪˈkeɪʃən/', 'noun', '{"zh-TW":["書面溝通；文字溝通"],"en":["the transmission of information, ideas, or messages in written form"]}', NULL, 'effective written communication / written communication skills / improve written communication', '[{"en":"Clear written communication is essential in business, especially in emails and reports.","zh-TW":"清晰的書面溝通在商業中至關重要，特別是在電子郵件和報告中。"},{"en":"She improved her written communication skills by taking a business writing course.","zh-TW":"她通過參加商務寫作課程提高了書面溝通技能。"}]', NULL, NULL, 5, 7097, NULL),
(7098, 'written consent', '/ˈrɪtən kənˈsent/', 'noun', '{"zh-TW":["書面同意"],"en":["formal approval given in writing, required for many legal or contractual actions"]}', NULL, 'obtain written consent / provide written consent', '[{"en":"Written consent from the landlord is needed before subletting.","zh-TW":"轉租前需要獲得房東的書面同意。"},{"en":"The data collection requires written consent from each participant.","zh-TW":"資料收集需要每位參與者的書面同意。"}]', NULL, NULL, 5, 7098, NULL),
(7099, 'wrong', 'rɒŋ', 'adjective', '{"zh-TW":["錯誤的；不對的","不適當的"],"en":["not correct","morally bad"]}', NULL, 'wrong decision/go wrong', '[{"en":"We made the wrong decision initially.","zh-TW":"我們最初做出了錯誤的決定。"}]', '{"adverb":"wrongly"}', NULL, 2, 7099, NULL);